1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import type { NodeStatus, NodeProvider } from "@prisma/client";
7	import { db } from "@/lib/db";
8	import { requireAdmin } from "@/lib/auth";
9	import { pveFor } from "@/lib/proxmox";
10	import { isValidRegion } from "@/lib/node-regions";
11	import { encryptNodeAgentToken, agentHealth, type AgentNode } from "@/lib/node-agent";
12	
13	/**
14	 * Admin CRUD + health checks for compute nodes (Proxmox hypervisors).
15	 *
16	 * Multi-node correctness rules enforced here:
17	 *  - Each node lives in its own NAT /24 (`subnetPrefix`). Two nodes may reuse
18	 *    the same guest-IP range ONLY if they sit in different subnets — so we only
19	 *    flag an IP overlap when the subnetPrefix matches.
20	 *  - SSH DNAT forwards happen on each node's own host, so port ranges may repeat
21	 *    across different hosts. They only conflict when two Node rows point at the
22	 *    same public IP (same host) with overlapping port ranges.
23	 *  - `natChain` is the iptables chain the worker rebuilds from the DB; it must be
24	 *    globally unique so one node's rebuild never clobbers another's rules.
25	 */
26	
27	type FormState = { error?: string; ok?: boolean };
28	
29	async function audit(userId: string | null, action: string, detail?: string) {
30	  await db.auditLog.create({ data: { userId, action, detail } });
31	}
32	
33	function rangesOverlap(aStart: number, aEnd: number, bStart: number, bEnd: number): boolean {
34	  return aStart <= bEnd && bStart <= aEnd;
35	}
36	
37	/** Suggest sane, non-colliding defaults for the Nth node (1-based ordinal of the new node). */
38	export async function suggestNodeDefaults(): Promise<{
39	  ordinal: number;
40	  subnetPrefix: string;
41	  natChain: string;
42	  ipStart: number;
43	  ipEnd: number;
44	  sshPortStart: number;
45	  sshPortEnd: number;
46	}> {
47	  await requireAdmin();
48	  const count = await db.node.count();
49	  const ordinal = count + 1;
50	  // node #1 → 10.20.0. / NXEON_FWD ; node #2 → 10.20.1. / NXEON_FWD_N2 ; ...
51	  const subnetPrefix = `10.20.${ordinal - 1}.`;
52	  const natChain = ordinal === 1 ? "NXEON_FWD" : `NXEON_FWD_N${ordinal}`;
53	  return { ordinal, subnetPrefix, natChain, ipStart: 100, ipEnd: 250, sshPortStart: 20000, sshPortEnd: 29999 };
54	}
55	
56	const nodeSchema = z.object({
57	  name: z.string().min(1).max(60).regex(/^[a-zA-Z0-9._-]+$/, "Name: letters, digits, . _ - only."),
58	  pveNode: z.string().min(1).max(60).regex(/^[a-zA-Z0-9.-]+$/, "Invalid Proxmox node name."),
59	  apiUrl: z.string().url().max(200).refine((u) => u.startsWith("http"), "API URL must be http(s)."),
60	  tokenId: z.string().min(1).max(120).regex(/^[^\s]+![^\s]+$/, "Token ID looks like user@realm!tokenname."),
61	  tokenSecret: z.string().min(1).max(200),
62	  publicIp: z.string().min(1).max(60),
63	  bridge: z.string().min(1).max(20).regex(/^[a-z0-9]+$/, "Bridge: e.g. vmbr1."),
64	  subnetPrefix: z
65	    .string()
66	    .regex(/^\d{1,3}\.\d{1,3}\.\d{1,3}\.$/, "Subnet prefix must be a /24 like 10.20.1. (trailing dot)."),
67	  ipStart: z.coerce.number().int().min(2).max(254),
68	  ipEnd: z.coerce.number().int().min(2).max(254),
69	  sshPortStart: z.coerce.number().int().min(1024).max(65535),
70	  sshPortEnd: z.coerce.number().int().min(1024).max(65535),
71	  natChain: z.string().min(1).max(40).regex(/^[A-Z0-9_]+$/, "NAT chain: UPPERCASE letters, digits, _ only."),
72	  storageNvme: z.string().min(1).max(60),
73	  storageHdd: z.string().min(1).max(60),
74	  capacityRamMB: z.coerce.number().int().min(1024).max(4_000_000),
75	  enabled: z.boolean().default(true),
76	  isPrimary: z.boolean().default(false),
77	  status: z.enum(["ONLINE", "OFFLINE", "MAINTENANCE"]).default("ONLINE"),
78	  provider: z.enum(["OVH", "HETZNER"]).default("OVH"),
79	  region: z.string().min(1).max(20).regex(/^[a-z0-9]+$/, "Region must be a lowercase datacenter code, e.g. fsn1."),
80	  providerServerId: z.string().max(120).optional().transform((v) => (v ? v : null)),
81	  agentPort: z.coerce.number().int().min(1).max(65535).default(8943),
82	  // Blank means "leave whatever is already stored unchanged" — mirrors
83	  // tokenSecret's own edit-form convention. Only a non-blank value is ever
84	  // written, and only as an encrypted value (lib/node-agent.ts) — never
85	  // redisplayed once saved, unlike tokenSecret (see addNode/updateNode).
86	  agentToken: z.string().max(200).optional().transform((v) => (v ? v.trim() : "")),
87	});
88	
89	type NodeInput = z.infer<typeof nodeSchema>;
90	
91	function parseNodeForm(formData: FormData) {
92	  return nodeSchema.safeParse({
93	    name: (formData.get("name") ?? "").toString().trim(),
94	    pveNode: (formData.get("pveNode") ?? "").toString().trim(),
95	    apiUrl: (formData.get("apiUrl") ?? "").toString().trim(),
96	    tokenId: (formData.get("tokenId") ?? "").toString().trim(),
97	    tokenSecret: (formData.get("tokenSecret") ?? "").toString().trim(),
98	    publicIp: (formData.get("publicIp") ?? "").toString().trim(),
99	    bridge: (formData.get("bridge") ?? "vmbr1").toString().trim(),
100	    subnetPrefix: (formData.get("subnetPrefix") ?? "").toString().trim(),
101	    ipStart: formData.get("ipStart"),
102	    ipEnd: formData.get("ipEnd"),
103	    sshPortStart: formData.get("sshPortStart"),
104	    sshPortEnd: formData.get("sshPortEnd"),
105	    natChain: (formData.get("natChain") ?? "").toString().trim(),
106	    storageNvme: (formData.get("storageNvme") ?? "vmdata").toString().trim(),
107	    storageHdd: (formData.get("storageHdd") ?? "vmdata-hdd").toString().trim(),
108	    capacityRamMB: formData.get("capacityRamMB"),
109	    enabled: formData.get("enabled") != null,
110	    isPrimary: formData.get("isPrimary") != null,
111	    status: (formData.get("status") ?? "ONLINE").toString(),
112	    provider: (formData.get("provider") ?? "OVH").toString(),
113	    region: (formData.get("region") ?? "").toString().trim(),
114	    providerServerId: (formData.get("providerServerId") ?? "").toString().trim(),
115	    agentPort: formData.get("agentPort"),
116	    agentToken: (formData.get("agentToken") ?? "").toString(),
117	  });
118	}
