169	export async function addNode(_prev: FormState, formData: FormData): Promise<FormState> {
170	  const admin = await requireAdmin();
171	  const parsed = parseNodeForm(formData);
172	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid node details." };
173	  const { agentToken, ...data } = parsed.data;
174	
175	  if (await db.node.findUnique({ where: { name: data.name } })) {
176	    return { error: `A node named "${data.name}" already exists.` };
177	  }
178	  const rangeError = await validateAgainstExisting(data);
179	  if (rangeError) return { error: rangeError };
180	
181	  let created;
182	  try {
183	    created = await db.node.create({
184	      data: { ...data, ...(agentToken ? { agentTokenEnc: encryptNodeAgentToken(agentToken) } : {}) },
185	    });
186	  } catch (e: any) {
187	    return { error: `Could not create node: ${String(e?.message ?? e).slice(0, 200)}` };
188	  }
189	  await audit(admin.id, "node.create", `${data.name} (${data.pveNode} @ ${data.apiUrl})`);
190	  revalidatePath("/admin/nodes");
191	  revalidatePath("/admin/infrastructure");
192	  redirect(`/admin/nodes/${created.id}`);
193	}
194	
195	export async function updateNode(_prev: FormState, formData: FormData): Promise<FormState> {
196	  const admin = await requireAdmin();
197	  const id = (formData.get("id") ?? "").toString();
198	  const existing = await db.node.findUnique({ where: { id } });
199	  if (!existing) return { error: "Node not found." };
200	
201	  const parsed = parseNodeForm(formData);
202	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid node details." };
203	  const { agentToken, ...data } = parsed.data;
204	
205	  const nameClash = await db.node.findUnique({ where: { name: data.name } });
206	  if (nameClash && nameClash.id !== id) return { error: `A node named "${data.name}" already exists.` };
207	
208	  const rangeError = await validateAgainstExisting(data, id);
209	  if (rangeError) return { error: rangeError };
210	
211	  try {
212	    // Blank agentToken means "leave whatever is already stored unchanged" —
213	    // omit the field entirely rather than writing over it, exactly like
214	    // tokenSecret already behaves on this same form.
215	    await db.node.update({
216	      where: { id },
217	      data: { ...data, ...(agentToken ? { agentTokenEnc: encryptNodeAgentToken(agentToken) } : {}) },
218	    });
219	  } catch (e: any) {
220	    return { error: `Could not update node: ${String(e?.message ?? e).slice(0, 200)}` };
221	  }
222	  await audit(admin.id, "node.update", `${data.name} (${id})`);
223	  revalidatePath("/admin/nodes");
224	  revalidatePath(`/admin/nodes/${id}`);
225	  revalidatePath("/admin/infrastructure");
226	  return { ok: true };
227	}
