229	export async function setNodeEnabled(id: string, enabled: boolean): Promise<FormState> {
230	  const admin = await requireAdmin();
231	  const node = await db.node.findUnique({ where: { id } });
232	  if (!node) return { error: "Node not found." };
233	  await db.node.update({ where: { id }, data: { enabled } });
234	  await audit(admin.id, enabled ? "node.enable" : "node.disable", node.name);
235	  revalidatePath("/admin/nodes");
236	  revalidatePath(`/admin/nodes/${id}`);
237	  return { ok: true };
238	}
