240	/**
241	 * Toggle whether NEW server orders may land on this node (lib/node-capacity.ts
242	 * scheduleNode). Distinct from setNodeEnabled: the node stays fully visible in
243	 * every admin surface and its existing servers are completely unaffected —
244	 * this only removes it from the pool a fresh provision picks from.
245	 */
246	export async function setNodeAcceptsProvisions(id: string, acceptsProvisions: boolean): Promise<FormState> {
247	  const admin = await requireAdmin();
248	  const node = await db.node.findUnique({ where: { id } });
249	  if (!node) return { error: "Node not found." };
250	  await db.node.update({ where: { id }, data: { acceptsProvisions } });
251	  await audit(admin.id, acceptsProvisions ? "node.provisions_enable" : "node.provisions_disable", node.name);
252	  revalidatePath("/admin/infrastructure");
253	  revalidatePath("/admin/nodes");
254	  revalidatePath(`/admin/nodes/${id}`);
255	  return { ok: true };
256	}
