258	export async function setNodeStatus(id: string, status: NodeStatus): Promise<FormState> {
259	  const admin = await requireAdmin();
260	  const node = await db.node.findUnique({ where: { id } });
261	  if (!node) return { error: "Node not found." };
262	  await db.node.update({ where: { id }, data: { status } });
263	  await audit(admin.id, "node.status", `${node.name} → ${status}`);
264	  revalidatePath("/admin/nodes");
265	  revalidatePath(`/admin/nodes/${id}`);
266	  return { ok: true };
