269	export type TestNodeResult = {
270	  ok: boolean;
271	  message: string;
272	  uptimeSec?: number;
273	  ramTotal?: number;
274	  ramUsed?: number;
275	  cpu?: number;
276	  pveVersion?: string;
277	  checkedAt: string;
278	  // Node-agent reachability — a SEPARATE service/port from Proxmox, so a
279	  // separate result. Omitted entirely for the primary (which never runs one).
280	  agentOk?: boolean;
281	  agentMessage?: string;
282	};
283	
284	/** Probe this node's node-agent, if it isn't the primary. Never throws. */
285	async function probeAgent(node: AgentNode & { isPrimary: boolean }): Promise<{ agentOk?: boolean; agentMessage?: string }> {
286	  if (node.isPrimary) return {};
287	  if (!node.agentTokenEnc) return { agentOk: false, agentMessage: "No agent token configured yet." };
288	  try {
289	    const h = await agentHealth(node);
290	    return { agentOk: !!h?.ok, agentMessage: h?.ok ? "Node-agent reachable." : "Node-agent responded, but not healthy." };
291	  } catch (e: any) {
292	    return { agentOk: false, agentMessage: String(e?.message ?? e).slice(0, 200) };
293	  }
294	}
295	
296	/** Live health check: hit the node's Proxmox API (and its node-agent, if any), record status + lastSeenAt. */
297	export async function testNode(id: string): Promise<TestNodeResult> {
298	  const admin = await requireAdmin();
299	  const node = await db.node.findUnique({ where: { id } });
300	  const checkedAt = new Date().toISOString();
301	  if (!node) return { ok: false, message: "Node not found.", checkedAt };
302	
303	  const client = pveFor({
304	    apiUrl: node.apiUrl,
305	    pveNode: node.pveNode,
306	    tokenId: node.tokenId,
307	    tokenSecret: node.tokenSecret,
308	  });
309	
310	  const agentResult = await probeAgent(node);
311	
312	  try {
313	    const s = await client.get(`/nodes/${client.node}/status`);
314	    await db.node.update({
315	      where: { id },
316	      data: {
317	        lastSeenAt: new Date(),
318	        // Don't override an operator-set MAINTENANCE flag with ONLINE.
319	        status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "ONLINE",
320	      },
321	    });
322	    await audit(admin.id, "node.test.ok", node.name);
323	    revalidatePath("/admin/nodes");
324	    revalidatePath(`/admin/nodes/${id}`);
325	    return {
326	      ok: true,
327	      message: "Proxmox API reachable.",
328	      uptimeSec: typeof s?.uptime === "number" ? s.uptime : undefined,
329	      ramTotal: s?.memory?.total,
330	      ramUsed: s?.memory?.used,
331	      cpu: typeof s?.cpu === "number" ? s.cpu : undefined,
332	      pveVersion: typeof s?.pveversion === "string" ? s.pveversion : undefined,
333	      checkedAt,
334	      ...agentResult,
335	    };
336	  } catch (e: any) {
337	    await db.node.update({
338	      where: { id },
339	      data: { status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "OFFLINE" },
340	    });
341	    await audit(admin.id, "node.test.fail", `${node.name}: ${String(e?.message ?? e).slice(0, 160)}`);
342	    revalidatePath("/admin/nodes");
343	    revalidatePath(`/admin/nodes/${id}`);
344	    return { ok: false, message: `Unreachable: ${String(e?.message ?? e).slice(0, 200)}`, checkedAt, ...agentResult };
345	  }
346	}
