348	export async function deleteNode(id: string): Promise<FormState> {
349	  const admin = await requireAdmin();
350	  const node = await db.node.findUnique({
351	    where: { id },
352	    include: { _count: { select: { servers: true } } },
353	  });
354	  if (!node) return { error: "Node not found." };
355	  if (node.isPrimary) return { error: "Refusing to delete the primary node." };
356	  if (node._count.servers > 0) {
357	    return {
358	      error: `Cannot delete "${node.name}" — ${node._count.servers} server(s) are still assigned to it. Migrate or remove them first.`,
359	    };
360	  }
361	  await db.node.delete({ where: { id } });
362	  await audit(admin.id, "node.delete", node.name);
363	  revalidatePath("/admin/nodes");
364	  revalidatePath("/admin/infrastructure");
365	  redirect("/admin/nodes");
366	}
