1	// Per-node capacity / utilization math for the node-capacity warning feature.
2	//
3	// Plain (non-"use server") module — safe to import from admin server components
4	// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
5	// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
6	// off it). No mutations here; the alert lifecycle lives in the worker so this
7	// file stays a pure-ish reader other surfaces can share, exactly like the
8	// read-only helpers in lib/monitoring.ts.
9	//
10	// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
11	// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
12	// new work when they do, so both are reduced to the same shape: a list of
13	// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
14	// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
15	//
16	// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
17	//   - allocation: what the DB has COMMITTED to the node (sum of every server's
18	//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
19	//     provision fail — a node can be 100% committed while barely warm.
20	//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
21	//     which is what makes a node DEGRADE.
22	// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
23	// which is the honest "add a node before this bites" signal the feature exists
24	// to give.
25	
26	import { db } from "./db";
27	import type { NodeProvider } from "@prisma/client";
28	import { nodeRamUsage, nodeStorageUsage, backupSummary, BACKUP_STALE_MS, type NodeRam, type StorageUsage } from "./monitoring";
29	import { effectiveDiskGB, baseDiskGBFor } from "./extra-disk";
30	import { getSettingInt } from "./settings";
31	// severityFor/capBarColor/CapSeverity/NodeThresholds live in capacity-severity.ts
32	// (a dependency-free, client-safe module) and are re-exported here unchanged —
33	// see that file's doc comment for why they were split out.
34	import { severityFor, capBarColor, type CapSeverity, type NodeThresholds } from "./capacity-severity";
35	
36	export { severityFor, capBarColor, type CapSeverity, type NodeThresholds };
37	
38	const MB = 1024 * 1024;
39	const GB = 1024 ** 3;
40	
41	export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS" | "BACKUP";
42	export type NodeKind = "PROXMOX" | "HOSTING";
43	
44	export const NODE_CAP_DEFAULT_WARN = 80;
45	export const NODE_CAP_DEFAULT_CRIT = 90;
46	
47	/**
48	 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
49	 * points BELOW the WARN threshold. Without the gap a node parked right on the
50	 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
51	 * churn. Env-overridable for tuning without a redeploy.
52	 */
53	export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);
54	
55	/**
56	 * A persistent (unchanged-severity) condition re-notifies at most once per this
57	 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
58	 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
59	 * immediately regardless of the cooldown.
60	 */
61	export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);
62	
63	/**
64	 * Every server status EXCEPT DELETING still holds committed capacity on its node
65	 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
66	 * matches the exclusion the existing scheduler and infra pages already use
67	 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
68	 * scheduleNode commits against.
69	 */
70	const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
71	/** Hosting-account statuses that still occupy a slot / quota on their node. */
72	const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
73	
74	/**
75	 * Resolve the admin-configured thresholds, clamped so they are always usable:
76	 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
77	 * the amber band unreachable and every warn instantly read critical).
78	 */
79	export async function nodeThresholds(): Promise<NodeThresholds> {
80	  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
81	  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
82	  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
83	  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
84	  if (critPct < warnPct) critPct = warnPct;
85	  return { warnPct, critPct };
86	}
87	
88	
89	/** The percent below which an OPEN alert is allowed to auto-resolve. */
90	export function resolveFloor(t: NodeThresholds): number {
91	  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
92	}
93	
94	export type DimUtil = {
95	  dimension: CapDimension;
96	  /** The value thresholded — the worse of allocation and real usage. */
97	  pct: number;
98	  /** DB-committed percent (null when the dimension has no allocation basis). */
99	  allocPct: number | null;
100	  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
101	  realPct: number | null;
102	  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
103	  detail: string;
104	  /** `allocPct`'s own absolute breakdown alone, e.g. "48 / 56 GB" — for UIs that
105	   *  render committed and used as two separate rows instead of one combined
106	   *  line. Null exactly when `allocPct` is null. */
107	  allocDetail: string | null;
108	  /** `realPct`'s own absolute breakdown alone, e.g. "34 GB used" — same
109	   *  pairing as `allocDetail`, null exactly when `realPct` is null. */
110	  realDetail: string | null;
111	};
112	
113	export type NodeUtil = {
114	  kind: NodeKind;
115	  id: string;
116	  name: string;
117	  enabled: boolean;
118	  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
119	  reachable: boolean;
120	  dims: DimUtil[];
121	  /** Worst dimension percent across `dims` (0 when there are none). */
122	  worstPct: number;
123	  severity: CapSeverity;
124	};
125	
126	function pct(part: number, whole: number): number | null {
127	  if (!(whole > 0)) return null;
128	  return (part / whole) * 100;
129	}
130	
131	/** Combine allocation + real into the thresholded value (worse of the two). */
132	function worse(allocPct: number | null, realPct: number | null): number {
133	  return Math.max(allocPct ?? 0, realPct ?? 0);
134	}
135	
136	function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
137	  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
138	  return { worstPct, severity: severityFor(worstPct, t) };
139	}
