141	// ---------------------------------------------------------------------------
142	// Proxmox compute nodes
143	// ---------------------------------------------------------------------------
144	
145	/**
146	 * Utilization for every registered Proxmox node.
147	 *
148	 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
149	 * each live server's `plan.ramMB`; real usage from the node status endpoint when
150	 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
151	 * (physical thread count / storage pool size), so on an unreachable node they are
152	 * simply omitted rather than guessed — `reachable:false` tells the UI and the
153	 * sweep to treat their absence as "unknown", never as "recovered".
154	 */
155	export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
156	  const nodes = await db.node.findMany({
157	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
158	    include: {
159	      servers: {
160	        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
161	        select: {
162	          extraDiskGB: true,
163	          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
164	          gamePlan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
165	        },
166	      },
167	    },
168	  });
169	
170	  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
171	  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
172	  let ramRows: NodeRam[] = [];
173	  let storageRows: StorageUsage[] = [];
174	  let backupRows: Awaited<ReturnType<typeof backupSummary>> = [];
175	  try {
176	    ramRows = await nodeRamUsage();
177	  } catch {
178	    /* leave empty — every node reads unreachable */
179	  }
180	  try {
181	    storageRows = await nodeStorageUsage();
182	  } catch {
183	    /* leave empty */
184	  }
185	  try {
186	    backupRows = await backupSummary();
187	  } catch {
188	    /* leave empty — BACKUP dim simply omitted below, same as an unreachable CPU/DISK */
189	  }
190	  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
191	  const backupByNode = new Map(backupRows.map((b) => [b.node, b]));
192	
193	  return nodes.map((n) => {
194	    // A game server's real commitment is its game plan's, not the (larger)
195	    // base VPS plan it rides on — see lib/extra-disk.ts's baseDiskGBFor.
196	    const committedRamMB = n.servers.reduce((s, sv) => s + (sv.gamePlan?.ramMB ?? sv.plan.ramMB), 0);
197	    const committedDiskGB = n.servers.reduce(
198	      (s, sv) => s + effectiveDiskGB(baseDiskGBFor(sv), sv.extraDiskGB),
199	      0,
200	    );
201	    const committedVcpu = n.servers.reduce((s, sv) => s + (sv.gamePlan?.cpuCores ?? sv.plan.cpuCores), 0);
202	
203	    const real = ramByNode.get(n.name);
204	    const reachable = !!real?.reachable;
205	    // The node's own VM-disk pool (storageNvme) is the disk denominator.
206	    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);
207	
208	    const dims: DimUtil[] = [];
209	
210	    // RAM — allocation always available; real when reachable.
211	    {
212	      const allocPct = pct(committedRamMB, n.capacityRamMB);
213	      const realPct = reachable && real ? real.ratio * 100 : null;
214	      const p = worse(allocPct, realPct);
215	      const allocDetail = `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB`;
216	      const realDetail = realPct !== null && real ? `${(real.used / GB).toFixed(0)} GB used` : null;
217	      const parts = [`${allocDetail} committed`];
218	      if (realDetail) parts.push(realDetail);
219	      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
220	    }
221	
222	    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
223	    // allocation ratio is context, not an alarm). Only present when reachable.
224	    if (reachable && real) {
225	      const realPct = real.cpu * 100;
226	      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
227	      const allocDetail = allocPct !== null ? `${committedVcpu} vCPU / ${real.cores} threads` : null;
228	      const realDetail = `${Math.round(realPct)}% used`;
229	      const parts = [realDetail];
230	      if (allocDetail) parts.push(`${allocDetail} (${Math.round(allocPct!)}% committed)`);
231	      // CPU is thresholded on REAL load only; overcommit alloc is informational.
232	      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
233	    }
234	
235	    // DISK — needs the pool size from Proxmox. Allocation = committed effective
236	    // disk vs pool total; real = pool used vs pool total. Worse of the two.
237	    if (vmStorage?.reachable && vmStorage.total > 0) {
238	      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
239	      const realPct = vmStorage.ratio * 100;
240	      const p = worse(allocPct, realPct);
241	      const allocDetail = `${committedDiskGB} GB / ${(vmStorage.total / GB).toFixed(0)} GB`;
242	      const realDetail = `${(vmStorage.ratio * (vmStorage.total / GB)).toFixed(0)} GB used`;
243	      dims.push({
244	        dimension: "DISK",
245	        pct: p,
246	        allocPct,
247	        realPct,
248	        detail: `${allocDetail} committed · ${Math.round(realPct)}% used`,
249	        allocDetail,
250	        realDetail,
251	      });
252	    }
253	
254	    // BACKUP — no allocation concept; thresholded on how stale the newest backup
255	    // is versus BACKUP_STALE_MS (so it crosses WARN/CRITICAL at 80%/90% of the
256	    // staleness window, reusing the same admin-configured thresholds as the other
257	    // dimensions). A node whose storage answers but shows zero backups EVER is
258	    // treated as maximally stale (100%) — that is precisely the "silently-broken
259	    // schedule on a node nobody's watching" case this dimension exists to catch.
260	    // Omitted entirely when the storage itself is unreachable — unknown, not OK.
261	    {
262	      const b = backupByNode.get(n.name);
263	      if (b?.reachable) {
264	        const ageMs = b.newestCtime !== null ? Date.now() - b.newestCtime * 1000 : null;
265	        const p = ageMs === null ? 100 : Math.min(100, (ageMs / BACKUP_STALE_MS) * 100);
266	        const detail =
267	          ageMs === null
268	            ? `No backups found on this node's storage (${b.count} on disk).`
269	            : `Newest backup ${Math.round(ageMs / 3_600_000)}h old · ${b.count} on disk (stale past ${Math.round(BACKUP_STALE_MS / 3_600_000)}h).`;
270	        dims.push({ dimension: "BACKUP", pct: p, allocPct: null, realPct: p, detail, allocDetail: null, realDetail: detail });
271	      }
272	    }
273	
274	    return {
275	      kind: "PROXMOX" as const,
276	      id: n.id,
277	      name: n.name,
278	      enabled: n.enabled,
279	      reachable,
280	      dims,
281	      ...rollup(dims, t),
282	    };
283	  });
284	}
285	
286	// ---------------------------------------------------------------------------
287	// Shared-hosting nodes
288	// ---------------------------------------------------------------------------
289	
290	/**
291	 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
292	 * quotas live in our own tables), so it is always reachable:
293	 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
294	 *     scheduler cap; the next account is refused once it's full.
295	 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
296	 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
297	 */
298	export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
299	  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });
300	
301	  return Promise.all(
302	    nodes.map(async (n) => {
303	      const [count, agg] = await Promise.all([
304	        db.hostingAccount.count({
305	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
306	        }),
307	        db.hostingAccount.aggregate({
308	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
309	          _sum: { diskQuotaMB: true, diskUsedMB: true },
310	        }),
311	      ]);
312	
313	      const totalDiskMB = n.diskTotalGB * 1024;
314	      const quotaMB = agg._sum.diskQuotaMB ?? 0;
315	      const usedMB = agg._sum.diskUsedMB ?? 0;
316	
317	      const dims: DimUtil[] = [];
318	
319	      // ACCOUNTS
320	      {
321	        const allocPct = pct(count, n.maxAccounts);
322	        const p = allocPct ?? 0;
323	        const allocDetail = `${count} / ${n.maxAccounts} accounts`;
324	        dims.push({
325	          dimension: "ACCOUNTS",
326	          pct: p,
327	          allocPct,
328	          realPct: null,
329	          detail: allocDetail,
330	          allocDetail,
331	          realDetail: null,
332	        });
333	      }
334	
335	      // DISK
336	      {
337	        const allocPct = pct(quotaMB, totalDiskMB);
338	        const realPct = pct(usedMB, totalDiskMB);
339	        const p = worse(allocPct, realPct);
340	        const allocDetail = `${(quotaMB / 1024).toFixed(0)} GB / ${n.diskTotalGB} GB`;
341	        const realDetail = realPct !== null ? `${(usedMB / 1024).toFixed(0)} GB used` : null;
342	        const parts = [`${allocDetail} quota`];
343	        if (realDetail) parts.push(realDetail);
344	        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
345	      }
346	
347	      return {
348	        kind: "HOSTING" as const,
349	        id: n.id,
350	        name: n.name,
351	        enabled: n.enabled,
352	        reachable: true,
353	        dims,
354	        ...rollup(dims, t),
355	      };
356	    }),
357	  );
358	}
