360	/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
361	export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
362	  const thresholds = await nodeThresholds();
363	  const [proxmox, hosting] = await Promise.all([
364	    proxmoxNodeUtil(thresholds),
365	    hostingNodeUtil(thresholds),
366	  ]);
367	  return { thresholds, nodes: [...proxmox, ...hosting] };
368	}
