370	/**
371	 * Pick the best Proxmox node for a new server of `planRamMB`, when the
372	 * customer didn't choose a location explicitly. Bin-packs onto whichever
373	 * ONLINE, enabled node has the most free RAM after projecting this VM onto
374	 * it, staying under the CRITICAL threshold when any node can (falling back to
375	 * least-bad if every node is already critical).
376	 *
377	 * THIRD copy, consolidated here. This existed as two near-identical private
378	 * copies — `lib/order.ts` (VPS orders) and `lib/actions-nxcloud.ts` (NxCloud
379	 * orders) — and `lib/game-order.ts`'s game-server order path never called
380	 * either one at all: it creates its `Server` row with no `nodeId`, so every
381	 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
382	 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
383	 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
384	 * RAM and 200% committed CPU while other nodes are comparatively idle, and
385	 * every game server in production has `nodeId: null`. Fixed by giving
386	 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
387	 * rather than writing a fourth copy or leaving it unscheduled.
388	 */
389	export async function scheduleNode(
390	  planRamMB: number,
391	  opts?: { provider?: NodeProvider; region?: string },
392	) {
393	  // Customer picks a REGION (e.g. "Singapore"), never a specific physical
394	  // node — multiple nodes can share one region (primary + node-3 are both
395	  // OVH/sgp1), and forcing a customer's choice onto one specific node meant
396	  // that node alone ever took new signups for that region, regardless of its
397	  // actual load relative to its sibling in the same region. Filtering here
398	  // (rather than a separate function) keeps this the single place "which
399	  // node wins" is decided, with or without a region constraint.
400	  const nodes = await db.node.findMany({
401	    where: {
402	      enabled: true,
403	      status: "ONLINE",
404	      // Distinct from `enabled` — a node can stay visible/online with its
405	      // existing servers running and still be excluded from taking NEW ones
406	      // (the admin Infrastructure page's per-node toggle).
407	      acceptsProvisions: true,
408	      ...(opts?.region ? { region: opts.region } : {}),
409	      ...(opts?.provider ? { provider: opts.provider } : {}),
410	    },
411	  });
412	  if (nodes.length === 0) return null;
413	  const loads = await Promise.all(
414	    nodes.map(async (n) => {
415	      const agg = await db.server.findMany({
416	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
417	        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
418	      });
419	      // A game server's real commitment is its game plan's ram, not the
420	      // (larger) base VPS plan it rides on — overstating every game server's
421	      // load here skews which node the scheduler picks for the NEXT one.
422	      const used = agg.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
423	      // Commitment AFTER this VM lands — that's what decides whether placing
424	      // here tips the node critical.
425	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
426	      return { node: n, free: n.capacityRamMB - used, projectedPct };
427	    }),
428	  );
429	  const { critPct } = await nodeThresholds();
430	  const roomy = loads.filter((l) => l.projectedPct < critPct);
431	  const pool = roomy.length > 0 ? roomy : loads;
432	  pool.sort((a, b) => b.free - a.free);
433	  return pool[0].node;
434	}
