436	/**
437	 * True only when EVERY enabled compute node is at/above its RAM warn
438	 * threshold — the signal for the public "reserve your server now" banner.
439	 * A single loaded node must NOT trigger this: `scheduleNode()` can still
440	 * place a new order on a roomier node, so warning the public the moment
441	 * only one host is busy would be a false "we're out of capacity" claim.
442	 * Deliberately internals-free for the caller — no node names, no percentages,
443	 * no "Host"/"committed RAM" — this is a customer-facing scarcity signal, not
444	 * an ops metric (see lib/capacity.ts's ops-facing capacitySnapshot for that).
445	 */
446	export async function fleetNearCapacity(): Promise<boolean> {
447	  const t = await nodeThresholds();
448	  const nodes = (await proxmoxNodeUtil(t)).filter((n) => n.enabled);
449	  if (nodes.length === 0) return false;
450	  return nodes.every((n) => {
451	    const ram = n.dims.find((d) => d.dimension === "RAM");
452	    return (ram?.pct ?? 0) >= t.warnPct;
453	  });
454	}
