103	  // plans at their flat rate, term prices divided down to a month, and nothing
104	  // counted for a suspended machine the renewal sweep will never charge.
105	  const mrrCents = fleetMrrCents(activeServers, renewalPrices);
106	  const billableServers = activeServers.filter((s) => s.status !== "SUSPENDED").length;
107	
108	  // Revenue last 14 days, grouped by day
109	  const days: string[] = [];
110	  const revByDay = new Map<string, number>();
111	  for (let i = 13; i >= 0; i--) {
112	    const k = dayKey(new Date(Date.now() - i * 86400_000));
113	    days.push(k);
114	    revByDay.set(k, 0);
115	  }
116	  for (const tx of revenueTx) {
117	    const k = dayKey(tx.createdAt);
118	    if (revByDay.has(k)) revByDay.set(k, (revByDay.get(k) ?? 0) + Math.abs(tx.amountCents));
119	  }
120	  const revSeries = days.map((k) => (revByDay.get(k) ?? 0) / 100);
121	  const revTotal14d = revSeries.reduce((a, b) => a + b, 0);
122	
123	  // Live hypervisor + storage, aggregated across every enabled node — this is
124	  // the fleet-wide command-center summary, so a second (Hetzner) node's
125	  // numbers must be folded in, not silently dropped. One unreachable node
126	  // doesn't blank the whole card; per-node detail lives on /admin/infrastructure.
127	  const liveNodes = await db.node.findMany({ where: { enabled: true }, orderBy: [{ isPrimary: "desc" }] });
128	  const nodeReads = await Promise.all(
129	    liveNodes.map(async (n) => {
130	      const client = pveForNode(n);
131	      let status: any = null;
132	      let vmdata: any = null;
133	      let backup: any = null;
134	      try {
135	        [status, vmdata, backup] = await Promise.all([
136	          nodeStatus(client),
137	          storageStatus(n.storageNvme, client),
138	          storageStatus("backup", client),
139	        ]);
140	      } catch {
141	        // this node's Proxmox API is unreachable — the others still count
142	      }
143	      return { n, status, vmdata, backup };
144	    })
145	  );
146	  const reachable = nodeReads.filter((r) => r.status);
147	  const node = reachable[0]?.status ?? null; // primary (or first reachable) — for uptime/load/kernel, which don't aggregate
148	  const anyReachable = reachable.length > 0;
149	
150	  const cpuThreadsTotal = reachable.reduce((n, r) => n + (r.status.cpuinfo?.cpus ?? 0), 0);
151	  const cpuUsedThreads = reachable.reduce((n, r) => n + (r.status.cpu ?? 0) * (r.status.cpuinfo?.cpus ?? 0), 0);
152	  const fleetCpuPct = cpuThreadsTotal > 0 ? (cpuUsedThreads / cpuThreadsTotal) * 100 : 0;
153	  const memUsedTotal = reachable.reduce((n, r) => n + (r.status.memory?.used ?? 0), 0);
154	  const memTotalTotal = reachable.reduce((n, r) => n + (r.status.memory?.total ?? 0), 0);
155	
156	  const vmdataUsed = nodeReads.reduce((n, r) => n + (r.vmdata?.used ?? 0), 0);
157	  const vmdataTotal = nodeReads.reduce((n, r) => n + (r.vmdata?.total ?? 0), 0);
158	  const backupUsed = nodeReads.reduce((n, r) => n + (r.backup?.used ?? 0), 0);
159	  const backupTotal = nodeReads.reduce((n, r) => n + (r.backup?.total ?? 0), 0);
160	  const vmdata = vmdataTotal > 0 ? { used: vmdataUsed, total: vmdataTotal } : null;
161	  const backup = backupTotal > 0 ? { used: backupUsed, total: backupTotal } : null;
162	
163	  const uptimeDays = node ? Math.floor(node.uptime / 86400) : 0;
164	  const uptimeHours = node ? Math.floor((node.uptime % 86400) / 3600) : 0;
165	
166	  return (
167	    <div className="space-y-6">
168	      {activeJobs.length > 0 && <AutoRefresh />}
169	      <PageHeader title="Operations overview" sub="Live command center for the Nxeon platform.">
170	        <Link href="/admin/monitoring" className="btn-secondary">
171	          Monitoring
172	        </Link>
173	        <Link href="/admin/grant" className="btn-primary">
174	          Grant VPS
175	        </Link>
176	      </PageHeader>
177	
178	      {/* KPI row */}
179	      <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">
180	        <StatCard
181	          label="MRR"
182	          value={fmtMoney(mrrCents)}
183	          delta={
184	            billableServers === activeServers.length
185	              ? `${billableServers} billable servers`
186	              : `${billableServers} billable · ${activeServers.length - billableServers} suspended`
187	          }
188	          href="/admin/subscriptions"
189	        />
190	        <StatCard label="Active customers" value={String(serverOwners.length)} delta="with ≥1 server" href="/admin/users" />
191	        <StatCard
192	          label="Servers"
193	          value={String(totalServers)}
194	          delta={`${runningCount} running`}
