import type { Prisma } from "@prisma/client";
import { renewalCharge, type PricedServer, type RenewalPrices } from "./renewal-charge";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { extraDiskPerGbCents } from "./disk-expand";
import { backupPlusMonthlyCents } from "./backup-upgrade";
import { annualDiscountPct } from "./annual-discount";

/**
 * Shared arithmetic for the figures the admin console puts in front of an
 * operator. Everything here exists because a headline number on an ops dashboard
 * is a decision input, and every one of these was previously computed from
 * something other than what its label claimed.
 */

/* ------------------------------------------------------------------ *
 * Revenue
 * ------------------------------------------------------------------ */

/**
 * Ledger-description prefixes whose NEGATIVE rows are money LEAVING the business
 * (or an accounting correction), not revenue earned.
 *
 * REAL DEFECT (2026-07-27 admin audit). Every revenue figure in the console was
 * `SUM(-amountCents) WHERE amountCents < 0` — "any wallet debit is revenue". Four
 * paths write a negative wallet row that is the opposite of revenue:
 *
 *   - `refundPayment` (lib/actions-admin-billing.ts) writes `Refund — …` with
 *     `amountCents: -walletDebit`. Refunding a customer $200 therefore ADDED $200
 *     to "Revenue · 30d", "Revenue · all time", "Lifetime revenue", the 14-day
 *     revenue chart, "Revenue by month" and ARPU. A bad month of refunds read as
 *     a record month, in the direction that hides the problem.
 *   - `adjustBalance` writes `Admin balance adjustment…`, which is negative when
 *     an operator claws back a mistaken credit — again the reversal of revenue.
 *   - `requestAffiliatePayout` / `adminUpdatePayout` (lib/actions-affiliate.ts)
 *     write `Affiliate payout …` when commission is reserved for cash-out. That
 *     is a cost of sale being counted as a sale.
 *   - `Reversed downgrade credit (resize failed)` unwinds a credit we issued.
 *
 * Matching on description is not elegant — the ledger has no `kind` column — but
 * it is exact for the rows that exist, it is the same technique the "Credits
 * issued" card already used, and `test/admin-console-guards.test.ts` enumerates
 * every `walletTransaction.create` description literal in the repo and fails if a
 * new one is not classified here. A new ledger row cannot silently join the
 * revenue line.
 */
export const NON_REVENUE_PREFIXES = [
  "Refund",
  "Admin balance adjustment",
  "Affiliate payout",
  "Reversed downgrade credit",
  "Write-off",
] as const;

/** True when a negative ledger row of this description represents earned revenue. */
export function isRevenueDescription(description: string): boolean {
  return !NON_REVENUE_PREFIXES.some((p) => description.startsWith(p));
}

/**
 * User `where` fragment for accounts that COUNT toward the business numbers.
 * Excludes accounts flagged `excludeFromRevenue` (the owner's own/test/staff
 * accounts) so internal usage never inflates Revenue/MRR. Spread as `user: …`
 * into any revenue/MRR query that joins a User (wallet rows, servers, invoices).
 */
export const REVENUE_USER_WHERE: Prisma.UserWhereInput = { excludeFromRevenue: false };

/**
 * Prisma `where` fragment selecting the wallet rows that are genuinely revenue:
 * a debit whose description is not one of the reversals above, AND whose owner is
 * a revenue-counting account. Spread it into a query alongside any date range.
 */
export const REVENUE_WHERE: Prisma.WalletTransactionWhereInput = {
  amountCents: { lt: 0 },
  NOT: NON_REVENUE_PREFIXES.map((p) => ({ description: { startsWith: p } })),
  user: REVENUE_USER_WHERE,
};

/**
 * Descriptions of POSITIVE rows that are an operator handing out money — the
 * "Credits issued" figure on /admin/billing. There are two admin credit tools and
 * the card only ever matched one of them: `adminCreditUser` writes "Admin credit
 * adjustment", `adjustBalance` (the control rendered on that very page, and on
 * every invoice) writes "Admin balance adjustment". Goodwill issued through the
 * page's own form was invisible in the page's own total.
 */
export const ADMIN_CREDIT_WHERE: Prisma.WalletTransactionWhereInput = {
  amountCents: { gt: 0 },
  OR: [
    { description: { startsWith: "Admin credit" } },
    { description: { startsWith: "Admin balance adjustment" } },
  ],
};

/* ------------------------------------------------------------------ *
 * MRR
 * ------------------------------------------------------------------ */

/**
 * The shape of a server row needed to price its monthly contribution —
 * exactly `PricedServer` (lib/renewal-charge.ts) plus the fields this file's
 * own free/suspended/deleting short-circuits need.
 */
export type MrrServer = PricedServer & {
  status: string;
  isFree: boolean;
};

/**
 * Fetches the four admin-priced renewal inputs together, ONCE, for callers
 * that need to price a whole fleet (serverMonthlyCents/fleetMrrCents below).
 * Deliberately NOT exported from lib/renewal-charge.ts itself — that file is
 * imported by a CLIENT component (the deploy wizard's term cards) and stays
 * free of anything that touches the database; every one of these four is a
 * `getSettingInt` read and must stay server-only.
 */
export async function currentRenewalPrices(): Promise<RenewalPrices> {
  const [ipMonthlyCents, extraDiskPerGbCentsVal, backupPlusCents, annualPct] = await Promise.all([
    dedicatedIpMonthlyCents(),
    extraDiskPerGbCents(),
    backupPlusMonthlyCents(),
    annualDiscountPct(),
  ]);
  return { ipMonthlyCents, extraDiskPerGbCents: extraDiskPerGbCentsVal, backupPlusCents, annualDiscountPct: annualPct };
}

/**
 * What one server actually contributes per month.
 *
 * REAL DEFECT (2026-07-27 admin audit, extended 2026-09-10). "MRR" on /admin,
 * /admin/subscriptions and /admin/analytics was `SUM(plan.priceCents)` over
 * every non-free, non-DELETING server. Four things were wrong with that, all
 * in the flattering direction:
 *
 *   1. GAME SERVERS. A game server carries BOTH a base `planId` and a
 *      `gamePlanId` and is sold at the game plan's flat price — the exact reason
 *      `renewNow` reads `gamePlan.priceCents` (lib/actions.ts) after billing a
 *      $4.99 tier at the $8.99 base rate. The dashboard still made that mistake.
 *   2. TERM PRICE. `plan.priceCents` is the monthly LIST price. A server bought
 *      on a discounted 36-month term is billed far less per month than list, so
 *      list-price MRR overstates committed revenue for every long-term customer.
 *      /admin/products already normalises its add-on MRR with a
 *      price-over-term division; VPS MRR did not.
 *   3. SUSPENDED SERVERS. The renewal sweep SKIPS suspended servers — an
 *      admin-suspended or abuse-suspended machine is never charged (see
 *      `adminSuspendServer`) — yet it counted at full price forever.
 *   4. ADD-ONS. Found live 2026-09-10 on a real customer: their invoice was
 *      $19.98 (plan $16.99 + a $2.99/mo dedicated-IP surcharge, correctly
 *      billed every renewal per worker/billing.ts's own sweep), but "Monthly
 *      spend" on their admin page showed $16.99 — this function never priced
 *      dedicated IP, extra disk, or the Plus backup tier at all, the exact
 *      "second formula" lib/renewal-charge.ts's own docstring warns never to
 *      write ("there is ONE renewal formula... two incidents in one day came
 *      from a second copy"). Now delegates to `renewalCharge` — the same
 *      formula worker/billing.ts's sweep actually charges from — instead of
 *      maintaining an independent, incomplete copy.
 *
 * Returns 0 for anything not currently billable.
 */
export function serverMonthlyCents(s: MrrServer, prices: RenewalPrices): number {
  if (s.isFree) return 0;
  // Not billed while suspended or being torn down.
  if (s.status === "SUSPENDED" || s.status === "DELETING") return 0;
  const charge = renewalCharge(s, prices);
  return monthlyCents(charge.netCents, charge.months);
}

/**
 * A term price expressed per month. Mirrors `monthlyCents` in
 * components/admin/ProductTables.tsx, which has always normalised the add-on
 * catalogue this way; VPS pricing simply never used it.
 */
export function monthlyCents(priceCents: number, termMonths: number): number {
  const months = Math.max(1, termMonths || 1);
  return Math.round(priceCents / months);
}

/** Sum `serverMonthlyCents` across a fleet. */
export function fleetMrrCents(servers: MrrServer[], prices: RenewalPrices): number {
  return servers.reduce((n, s) => n + serverMonthlyCents(s, prices), 0);
}

/* ------------------------------------------------------------------ *
 * Audit attribution
 * ------------------------------------------------------------------ */

/**
 * `audit()` in lib/actions.ts appends ` actingAdmin=<id>` to an AuditLog's DETAIL
 * when an admin is impersonating, while `userId` stays the impersonated CUSTOMER
 * — that is the whole point: the customer-scoped row keeps its customer.
 *
 * REAL DEFECT (2026-07-27 admin audit). Every surface that READS the audit log
 * (/admin/audit, the Logs → Audit tab, the Activity feed, the per-customer
 * "Recent activity" panel) rendered `userId`'s email as "Actor" and put `detail`
 * in a `max-w-md truncate` cell — so an action an admin took while impersonating
 * displayed the customer as the person who took it, and the one piece of evidence
 * that said otherwise is appended at the END of the string that gets clipped. The
 * mechanism was correct and the console hid it.
 */
export function actingAdminId(detail: string | null | undefined): string | null {
  const m = (detail ?? "").match(/actingAdmin=([A-Za-z0-9_-]+)/);
  return m ? m[1] : null;
}

/** `detail` with the `actingAdmin=…` marker removed, for display beside a badge. */
export function detailWithoutActor(detail: string | null | undefined): string {
  return (detail ?? "").replace(/\s*actingAdmin=[A-Za-z0-9_-]+\s*/, " ").trim();
}

