}

export function EnableToggle({ id, enabled }: { id: string; enabled: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-secondary py-1.5"
      disabled={pending}
      onClick={() => start(() => setNodeEnabled(id, !enabled).then(() => {}))}
