    </button>
  );
}

export function StatusSelect({ id, status }: { id: string; status: "ONLINE" | "OFFLINE" | "MAINTENANCE" }) {
  const [pending, start] = useTransition();
  return (
    <select
      className="input py-1.5"
      value={status}
      disabled={pending}
      onChange={(e) =>
        start(() => setNodeStatus(id, e.target.value as "ONLINE" | "OFFLINE" | "MAINTENANCE").then(() => {}))
      }
    >
      <option value="ONLINE">ONLINE</option>
      <option value="OFFLINE">OFFLINE</option>
      <option value="MAINTENANCE">MAINTENANCE</option>
    </select>
