}

export function DeleteNodeButton({
  id,
  name,
  serverCount,
  isPrimary,
}: {
  id: string;
  name: string;
  serverCount: number;
  isPrimary: boolean;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);

  const disabled = isPrimary || serverCount > 0;
  const reason = isPrimary
    ? "The primary node cannot be deleted."
    : serverCount > 0
      ? `${serverCount} server(s) still assigned — migrate them first.`
      : undefined;

  return (
    <div>
      <button
        className="btn-danger py-1.5"
        disabled={pending || disabled}
        title={reason}
        onClick={() => {
          if (!window.confirm(`Delete node "${name}"? This only removes the DB record, not the physical host.`)) return;
          start(async () => {
            const res = await deleteNode(id);
            if (res?.error) setErr(res.error);
            else router.push("/admin/nodes");
          });
        }}
      >
        {pending ? "Deleting…" : "Delete node"}
      </button>
      {reason && <p className="mt-1 text-xs text-slate-500">{reason}</p>}
      {err && <p className="mt-1 text-xs text-red-400">{err}</p>}
    </div>
  );
}

