capacityRamMB    Int           @default(56000)
// What the platform actually PAYS the infra provider (OVH/Hetzner/etc) to
// rent this physical box each month — admin-entered, not derived from
// anything else. Null (not 0) until an operator fills it in: a real node
// is never free, so 0 would misreport "unconfigured" as "no cost". Purely
// a cost/margin-visibility figure for /admin/nodes — never read by the
// scheduler or billing engine.
monthlyCostCents Int?
isPrimary        Boolean       @default(false)

/**
 * Admin-entered monthly lease/hosting cost for this node — what the platform
 * pays the infra provider (OVH/Hetzner/etc) to rent the physical box, used
 * only for margin visibility on /admin/nodes. `rawDollars` is the plain
 * dollar-amount string straight off the input (mirrors the
 * amount/step="0.01" convention already used by refund/credit forms in
 * lib/actions-admin-billing.ts); blank CLEARS it back to "not set" rather
 * than writing 0, since a real node is never free.
 */
export async function setNodeMonthlyCost(id: string, rawDollars: string): Promise<FormState> {
  const admin = await requireAdmin();
  const node = await db.node.findUnique({ where: { id } });
  if (!node) return { error: "Node not found." };

  const trimmed = rawDollars.trim();
  if (trimmed === "") {
    await db.node.update({ where: { id }, data: { monthlyCostCents: null } });
    await audit(admin.id, "node.cost.clear", node.name);
    revalidatePath("/admin/nodes");
    return { ok: true };
  }

  const dollars = Number(trimmed);
  if (!Number.isFinite(dollars) || dollars < 0 || dollars > 100_000) {
    return { error: "Enter a monthly cost between $0 and $100,000." };
  }
  const cents = Math.round(dollars * 100);
  await db.node.update({ where: { id }, data: { monthlyCostCents: cents } });
  await audit(admin.id, "node.cost.set", `${node.name} -> $${(cents / 100).toFixed(2)}/mo`);
  revalidatePath("/admin/nodes");
  return { ok: true };
}

