} from "@/lib/actions-nodes";

/**
 * Inline "type a dollar amount, it saves on blur" field for `Node.monthlyCostCents`
 * — the same "commit immediately via a server action, no separate save-then-navigate
 * step" convention as EnableToggle/StatusSelect above, just for a free-typed number
 * instead of a button/select. Dollars in the input, cents on the wire (mirrors the
 * amount/step="0.01" convention RefundControls/GiftCodeControls already use).
 * Blank clears the field back to "not set" — see setNodeMonthlyCost's own doc.
 */
export function NodeCostInput({ id, initialCents }: { id: string; initialCents: number | null }) {
  const asDollars = (c: number | null) => (c != null ? (c / 100).toFixed(2) : "");
  const [value, setValue] = useState(asDollars(initialCents));
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const lastSaved = asDollars(initialCents);

  const save = () => {
    if (value === lastSaved) return;
    setErr(null);
    start(async () => {
      const res = await setNodeMonthlyCost(id, value);
      if (res?.error) setErr(res.error);
      else {
        setSaved(true);
        setTimeout(() => setSaved(false), 1500);
      }
    });
  };

  return (
    <div>
      <div className="flex items-center gap-1">
        <span className="text-xs text-slate-500">$</span>
        <input
          className="input w-20 py-1 text-xs"
          type="number"
          step="0.01"
          min="0"
          placeholder="not set"
          value={value}
          disabled={pending}
          onChange={(e) => setValue(e.target.value)}
          onBlur={save}
          onKeyDown={(e) => {
            if (e.key === "Enter") e.currentTarget.blur();
          }}
        />
        <span className="text-[10px] text-slate-500">/mo</span>
      </div>
      {pending && <p className="mt-0.5 text-[10px] text-slate-500">saving…</p>}
      {saved && !pending && <p className="mt-0.5 text-[10px] text-emerald-400">saved</p>}
      {err && <p className="mt-0.5 text-[10px] text-red-400">{err}</p>}
    </div>
  );
}

