import { redirect } from "next/navigation";
import { LoginForm } from "@/components/AuthForms";
import { AuthShell } from "@/components/marketing/AuthShell";
import { realUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { googleOauthConfigured } from "@/lib/google-oauth";

/**
 * Dedicated login for the admin subdomain — app/admin/layout.tsx renders
 * this bare (no Shell, no auth requirement) for exactly this one sub-route;
 * everywhere else under /admin requires a signed-in ADMIN/SUPPORT/BILLING
 * account. Kept separate from the customer-facing /login (unreachable on
 * this host at all — see middleware.ts) so nobody lands on VPS-pitch copy
 * or a "Create account" link that makes no sense for an internal console.
 */
export default async function AdminLoginPage({
  searchParams,
}: {
  searchParams: Promise<{ error?: string }>;
}) {
  const { error } = await searchParams;

  // Already signed in as staff? Nothing to do here.
  const user = await realUser();
  if (user && isStaff(user.role)) redirect("/admin");

  return (
    <AuthShell heading="Nxeon Ops" sub="Sign in to the operations console." bullets={["Staff and admin accounts only", "Every action is audit-logged", "Contact the owner if you've lost access"]}>
      <LoginForm
        showRegisterLink={false}
        googleEnabled={googleOauthConfigured()}
        googleError={error === "account_suspended" ? "This account is suspended." : undefined}
      />
    </AuthShell>
  );
}

