import { db } from "../lib/db";

async function main() {
  const node = await db.node.findFirst({
    select: { id: true, name: true, monthlyCostCents: true },
  });
  if (!node) throw new Error("no node found on staging DB");
  console.log("BEFORE:", node);

  // Same write shape as setNodeMonthlyCost(id, "199.50") in lib/actions-nodes.ts.
  await db.node.update({ where: { id: node.id }, data: { monthlyCostCents: 19950 } });

  const reread = await db.node.findUnique({ where: { id: node.id }, select: { id: true, name: true, monthlyCostCents: true } });
  console.log("AFTER WRITE + REREAD:", reread);

  // Restore to prior value so this leaves no residue on staging.
  await db.node.update({ where: { id: node.id }, data: { monthlyCostCents: node.monthlyCostCents } });
  process.exit(0);
}
main().catch((e) => { console.error(e); process.exit(1); });

